const express = require('express');
const OpenApiValidator = require('express-openapi-validator');
const path = require('path');
const fs = require('fs');
const { CaseEvidence, LegalMatter } = require('../models/litigation');

const app = express();
app.use(express.json());

app.use(
  OpenApiValidator.middleware({
    apiSpec: path.join(__dirname, 'specs', 'legal-cases-spec.yaml'),
    validateRequests: true
  })
);

app.get('/api/v2/cases/:caseId/evidence/:evidenceId/download', async (req, res) => {
  if (!req.user || !req.user.attorneyId) {
    return res.status(401).json({ error: 'Attorney authentication required' });
  }

  const { caseId, evidenceId } = req.params;

  // Verify attorney has active assignment to this litigation case
  const matter = await LegalMatter.findOne({
    where: {
      id: caseId,
      assignedAttorneyId: req.user.attorneyId
    }
  });

  if (!matter) {
    return res.status(403).json({ error: 'Access denied: attorney not assigned to this matter' });
  }

  const evidence = await CaseEvidence.findOne({
    where: { id: evidenceId, caseId: caseId }
  });

  if (!evidence || !fs.existsSync(evidence.filePath)) {
    return res.status(404).json({ error: 'Evidence record or document file not found' });
  }

  res.setHeader('Content-Disposition', `attachment; filename="${evidence.filename}"`);
  res.sendFile(evidence.filePath);
});

app.listen(5006);
